@Component("priceBook-handler")
@ProcessingGroup("priceBook-processing-group")
public class PriceBookEventHandler {
	
	// core constructor
	PriceBookEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreatePriceBookEvent
     */
    @EventHandler
    public void handle( CreatePriceBookEvent event) {
        entityManager.persist(new PriceBook(event.getPriceBookId(), event.getName(), event.getAsActive(), event.getDescription(), event.getOrganization(), event.getEntries(), event.getQuotes(), event.getOrders()));
    }

    /*
     * @param	event UpdatePriceBookEvent
     */
    @EventHandler
    public PriceBook handle( UpdatePriceBookEvent event) {
    	entityManager.merge(new PriceBook(event.getPriceBookId(), event.getName(), event.getAsActive(), event.getDescription(), event.getOrganization(), event.getEntries(), event.getQuotes(), event.getOrders()));
    }
    
    /*
     * @param	event DeletePriceBookEvent
     */
    @EventHandler
    public void on( DeletePriceBookEvent event) {
    	PriceBook entity = new PriceBook();
   
    	// ------------------------------------------
    	// apply the PriceBookId
    	// ------------------------------------------
    	entity.setPriceBookId( event.getPriceBookId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final PriceBookRepository priceBookEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(PriceBookEventHandler.class.getName());

}
